#!/bin/sh
# Generated by frostfire. Writes the msmtp config from SMTP_* env vars so PHP's mail()
# relays straight to SendGrid (or any SMTP relay), then starts PHP-FPM.
# Shared by the Linux and FreeBSD images: MSMTPRC and MAIL_GROUP differ per OS.
set -eu

rc="${MSMTPRC:-/etc/msmtprc}"
group="${MAIL_GROUP:-www-data}"

if [ -n "${SMTP_HOST:-}" ]; then
    starttls=on
    [ "${SMTP_PORT:-587}" = "465" ] && starttls=off

    umask 027
    cat > "$rc" <<EOF
defaults
auth           on
tls            on
tls_starttls   ${starttls}
tls_trust_file ${TLS_TRUST_FILE:-/etc/ssl/certs/ca-certificates.crt}

account        default
host           ${SMTP_HOST}
port           ${SMTP_PORT:-587}
user           ${SMTP_USER:-}
password       ${SMTP_PASSWORD:-}
from           ${SMTP_FROM:-}
EOF
    chown "root:${group}" "$rc"
    chmod 0640 "$rc"
else
    echo "frostfire: SMTP_HOST is not set, outbound mail is disabled" >&2
fi

exec "$@"
